query:
SELECT state_name, status, candidate1_name, candidate1_party, candidate2_name, candidate2_party, called_winner
FROM senate_races WHERE state_name IN ('West Virginia', 'Nebraska');

SELECT state_name, district, status, candidate1_name, candidate2_name, called_winner
FROM house_races WHERE state_name IN ('West Virginia', 'Nebraska') ORDER BY state_name, district;

